steps.script:
var main = tree.root.get_node("Main")
var units = GameState.state["units"]
var spots = [Vector2(1000, 170), Vector2(1060, 150), Vector2(1120, 170), Vector2(1060, 80)]
var i = 0
for m in units["U_CUSTODIAN_GUARD_B"]["models"]:
	if not m.get("alive", true):
		continue
	m["position"] = {"x": spots[i].x, "y": spots[i].y}
	i += 1
units["U_WARBOSS_B"]["models"][0]["position"] = {"x": 1060.0, "y": 830.0}
main._recreate_unit_visuals()
return i

var list = tree.root.get_node("Main/HUD_Right/VBoxContainer/ShootingScrollContainer/ShootingPanel/DeclarationBox/ShooterUnitList")
if list.item_count <= 2 or not list.get_item_text(2).begins_with("Custodian Guard"):
	return "row 2 is not Custodian Guard"
list.get_v_scroll_bar().value = max(0.0, list.get_item_rect(2).get_center().y - list.size.y * 0.5)
return "ok"

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
var missing = 0
for l in lv.los_lines:
	if not l.has("block_at"):
		missing += 1
return missing

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
var bad = 0
for l in lv.los_lines:
	if not l.has("block_at"):
		continue
	var a: Vector2 = l["from"]
	var b: Vector2 = l["to"]
	var p: Vector2 = l["block_at"]
	var span: Vector2 = b - a
	var len2: float = max(span.length_squared(), 0.0001)
	var t: float = (p - a).dot(span) / len2
	var perp: float = p.distance_to(a + span * t)
	if t < -0.001 or t > 0.999 or perp > 0.5:
		bad += 1
return bad

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
var with_solid_run = 0
for l in lv.los_lines:
	if not l.has("block_at"):
		continue
	if l["from"].distance_to(l["block_at"]) > 20.0:
		with_solid_run += 1
return with_solid_run

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
var blocked = 0
var with_point = 0
for ol in lv.overview_lines:
	if ol["is_clear"]:
		continue
	blocked += 1
	if ol.has("block_at"):
		with_point += 1
return blocked - with_point

var lv = tree.root.get_node("Main/BoardRoot/LoSDebugVisual")
var n = 0
for ol in lv.overview_lines:
	if ol.has("block_at"):
		n += 1
return n
